package io.tenvyr.control.runtime;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Json;
import java.util.*;
public final class TeamTemplates {
    private TeamTemplates(){}
    public static ObjectNode configFromTeamTemplate(String id,JsonNode overrides){boolean review=id.equals("code-review");if(!review&&!id.equals("software-engineering"))throw new RuntimeFailure("TEMPLATE_NOT_FOUND","Unknown team template");ObjectNode bounds=Json.object("maxIterations",review?2:3,"maxWorkersPerIteration",review?3:4,"maxTotalWorkers",review?6:12,"loopDeadlineMs",review?2700000:3600000,"delegationDepthMax",1);for(String key:List.of("maxIterations","maxWorkersPerIteration","maxTotalWorkers","loopDeadlineMs"))if(overrides!=null&&overrides.has(key)){if(!overrides.get(key).isIntegralNumber()||overrides.get(key).asLong()<1||overrides.get(key).asLong()>bounds.get(key).asLong())throw new RuntimeFailure("CONFIG_INVALID","Template bounds may only be tightened");bounds.set(key,overrides.get(key));}ObjectNode config=Json.object("schemaVersion",1,"planner",Json.object("kind","connection","name",""),"verifier",Json.object("kind","connection","name",""),"allowedWorkers",Json.array(),"allowedExecutors",Json.array("local-host"));config.setAll(bounds);return config;}
    public static ArrayNode list(){ArrayNode result=Json.array();for(String id:List.of("software-engineering","code-review")){boolean review=id.equals("code-review");ObjectNode config=configFromTeamTemplate(id,null),bounds=Json.object();for(String k:List.of("maxIterations","maxWorkersPerIteration","maxTotalWorkers","loopDeadlineMs","delegationDepthMax"))bounds.set(k,config.get(k));result.add(Json.object("templateId",id,"name",review?"Code Review":"Software Engineering","description",review?"Planner scopes the review surface; parallel review workers; Verifier decides.":"Planner decomposes the goal; Workers implement/test/review as proposed; Verifier checks objective + evidence.","goalFraming",review?" Review the selected repository surface for correctness, security, and maintainability, and do not finish until the verifier accepts or limits are exhausted.":" Plan the work as a bounded task batch, implement with evidence, and do not finish until the verifier accepts or limits are exhausted.","defaultBounds",bounds,"configSkeleton",config,"roleSuggestions",Json.object("planner",config.get("planner"),"verifier",config.get("verifier"),"workerAgents",Json.array(review?"review":"implementation"))));}return result;}
}
